AuthResult authorize(AuthRequest req) {
    for (int attempt = 1; ; attempt++) {
        try {
            return issuer.authorize(req);
        } catch (IssuerTimeoutException e) {
            if (attempt == 3) throw e;                          // 1. bounded retries
            try {
                Thread.sleep(200L * attempt);
            } catch (InterruptedException ie) {
                Thread.currentThread().interrupt();             // 2. restore the request
                throw new AuthCancelledException(req.id(), ie); // 3. stop, and say why
            }
        }
    }
}

